<script setup lang="ts">
import {computed,onUnmounted,ref} from 'vue';
import type {PickerContext,PickerRow} from '../types/training-picker';
import MaterialPreview from '../components/MaterialPreview.vue';
const props=defineProps<{context:PickerContext}>(),s=ref(props.context.snapshot()),query=ref(s.value.query),a=props.context.actions;
const stop=props.context.subscribe(value=>{s.value=value;query.value=value.query});onUnmounted(stop);
const busy=computed(()=>s.value.loading||s.value.bulkPending||s.value.confirmPending);
const names:Record<string,string>={positive:'正样本',confirmed_negative:'当前目标已确认负样本',pending_negative:'目标范围待确认',pending_review:'正式标注需核验',used:'已有使用证据',possible:'可能已使用',selected:'仅有选择记录',unused:'有证据未使用',unknown:'历史未知',test_reserved:'独立 Test 保留',unannotated:'未标注',annotated:'已标注',confirmed_empty:'正式确认零框'};
const rows=computed(()=>s.value.items.map(row=>({...row,filename:row.filename||row.name||row.id})));
function reason(row:PickerRow){return row.training_usage?.reason||row.sample_role_issue_type||(row.selectable?'':'原资格规则限制')}
function filter(key:string,event:Event){a.filter(key,(event.target as HTMLInputElement).value)}
</script>
<template><section class="catalog-preview vue-training-picker" aria-label="Vue 训练素材选择器">
<header class="picker-top"><div><h2>{{ s.role==='test'?'独立 Test 素材':'本次训练素材' }}</h2><span>{{ s.total===null?'总数按需统计':`当前范围 ${s.total} 张` }} · 已选 {{ s.selectedCount }} 张</span></div><el-button @click="a.legacy()" :disabled="busy">使用原选择器</el-button></header>
<el-alert v-if="s.error" :title="s.error" type="error" :closable="false"/>
<div class="picker-layout"><aside><form @submit.prevent="a.search(query)"><el-input v-model="query" aria-label="搜索训练素材" placeholder="图片名称" :disabled="busy"/><el-button native-type="submit" :disabled="busy">搜索素材</el-button></form>
<details><summary>筛选条件</summary><label>排序<select :value="s.sortOrder" :disabled="busy" @change="a.sort(($event.target as HTMLSelectElement).value)"><option value="newest">最近加入</option><option value="oldest">最早加入</option></select></label>
<label>标注状态<select :value="s.filters.annotationState||''" :disabled="busy" @change="filter('annotationState',$event)"><option value="">全部</option><option value="annotated">已标注</option><option value="confirmed_empty">已确认零框</option><option value="unannotated">未标注</option></select></label>
<label>样本角色<select :value="s.sampleRole" :disabled="busy||s.role==='test'" @change="a.sampleRole(($event.target as HTMLSelectElement).value)"><option value="">未请求角色分类</option><option value="positive">正样本</option><option value="confirmed_negative">已确认负样本</option><option value="pending_negative">负样本待确认</option><option value="pending_review">标注需核验</option></select></label>
<label>存储来源 ID<input :value="s.filters.sourceIds?.toString()||''" placeholder="多个 ID 用逗号分隔" :disabled="busy" @change="filter('sourceIds',$event)"></label>
<label>历史使用<select :value="s.filters.usageState||''" :disabled="busy" @change="filter('usageState',$event)"><option value="">全部</option><option v-for="value in ['used','possible','selected','unused','unknown','test_reserved']" :key="value" :value="value">{{ names[value] }}</option></select></label>
<label>算法范围<select :value="s.filters.historyScope||''" :disabled="busy" @change="filter('historyScope',$event)"><option value="">全部算法范围</option><option value="current_only">当前算法使用过</option><option value="other_only">仅其他算法使用过</option></select></label>
<label v-if="s.role==='train'">素材范围<select :value="s.filters.negativePoolOnly?'pool':''" :disabled="busy" @change="filter('negativePoolOnly',$event)"><option value="">普通素材</option><option value="pool">当前算法负样本池</option></select></label>
<label>起始日期<input type="date" :value="s.filters.createdFrom||''" :disabled="busy" @change="filter('createdFrom',$event)"></label><label>截止日期<input type="date" :value="s.filters.createdTo||''" :disabled="busy" @change="filter('createdTo',$event)"></label></details>
<details><summary>标签筛选 · {{ s.labels.length }}</summary><button class="text-action" :disabled="busy" @click="a.clearLabels()">全部标签</button><label v-for="label in s.labelOptions" :key="label.code" class="label-option"><input type="checkbox" :checked="s.labels.includes(label.code)" :disabled="busy" @change="a.toggleLabel(label.code)">{{ label.display_name||label.name||label.code }}</label></details>
<label>历史复用策略<select :value="s.historyPolicy" :disabled="busy||!!s.reference" @change="a.historyPolicy(($event.target as HTMLSelectElement).value)"><option value="new_for_algorithm">仅本算法新素材</option><option value="include_history">包含已有历史</option></select></label>
</aside><main><div class="picker-tools"><div class="preview-actions"><el-button :disabled="busy||!!s.reference" @click="a.bulk('select-page')">选择本页</el-button><el-button :disabled="busy||!!s.reference" @click="a.bulk('select-filtered')">全选当前筛选</el-button><el-button :disabled="busy||!!s.reference" @click="a.bulk('select-all')">全选全部可用</el-button><el-button :disabled="busy" @click="a.bulk('clear-all')">清除选择</el-button></div><div class="preview-actions"><el-button :disabled="busy" @click="a.reload()">刷新</el-button><el-button @click="a.view(s.view==='list'?'grid':'list')">{{ s.view==='list'?'网格':'列表' }}</el-button></div></div>
<div v-if="s.reference" class="frozen-selection"><strong>服务器已冻结 {{ s.reference.count }} 张</strong><code>{{ s.reference.selection_ref }}</code><span>确认时重新核验有效期、身份与数量。修改范围须先清除选择。</span></div>
<div class="selection-summary"><el-button :disabled="busy" @click="a.summary()">读取标签与资格摘要</el-button><p v-if="s.summary">匹配 {{ s.summary.matched_count??'未提供' }} 张 · 可选 {{ s.summary.eligible_count??'未提供' }} 张 · 正样本标签 {{ Array.isArray(s.summary.positive_label_codes)?s.summary.positive_label_codes.join('、'):'未提供' }}</p></div><details class="selected-list"><summary>已选清单 · {{ s.selectedCount }} 张</summary><p v-if="s.reference">冻结清单由服务器保管，当前页勾选来自成员查询。</p><ul v-else><li v-for="row in s.selectedPreview" :key="row.id"><span>{{ row.name||row.id }}</span><el-button link :disabled="busy" @click="a.removeSelected(row.id)">移除</el-button></li></ul><p v-if="!s.reference&&s.selectedCount>s.selectedPreview.length">仅预览前 {{ s.selectedPreview.length }} 项，准确总数见上方。</p></details>
<el-skeleton v-if="s.loading&&!rows.length" :rows="6" animated/><el-empty v-else-if="!s.loading&&!rows.length" description="当前条件没有素材"/>
<div class="picker-rows" :class="s.view" :aria-busy="busy"><article v-for="row in rows" :key="row.id" class="picker-material" :class="{chosen:row.selected,blocked:!row.selectable}"><MaterialPreview :image="row" :project-id="context.projectId" :boxes="row.boxes||row.annotation_preview"/><div class="picker-copy"><label><input type="checkbox" :aria-label="`选择训练素材 ${row.filename}`" :checked="row.selected" :disabled="busy||!!s.reference||!row.selectable" @change="a.toggle(row.id,($event.target as HTMLInputElement).checked)"><span>{{ row.filename }}</span></label><p>{{ names[row.annotation_state||'']||row.annotation_state||'标注状态未提供' }} · {{ row.box_count??'—' }} 框</p><p>{{ names[row.sample_role||'']||row.sample_role||'角色按需读取' }} · {{ names[row.training_usage?.state||'unknown']||row.training_usage?.state }}</p><p v-if="!row.selectable" class="blocked-reason">{{ reason(row) }}</p></div></article></div>
<div class="picker-pagination"><el-button :disabled="busy||s.page<=1" @click="a.page(-1)">上一页素材</el-button><span>第 {{ s.page }} 页{{ s.total===null?'':` / ${s.totalPages}` }}</span><el-button :disabled="busy||!s.hasNext" @click="a.page(1)">下一页素材</el-button></div></main></div>
<footer class="picker-footer"><div><strong>已选 {{ s.selectedCount }} 张</strong><span>{{ s.reference?'服务器冻结引用':'逐张选择' }} · {{ s.role==='test'?'独立 Test':'Train' }}</span></div><div class="preview-actions"><el-button :disabled="s.confirmPending" @click="a.close()">取消选择</el-button><el-button type="primary" :disabled="busy" :loading="s.confirmPending" @click="a.confirm()">核验并确认选择</el-button></div></footer>
</section></template>
<style scoped>
.vue-training-picker{padding:16px;background:#fff;max-width:100%;min-width:0}.picker-top,.picker-tools,.picker-pagination,.picker-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.picker-top h2{font-size:18px;margin:0 0 5px}.picker-top span,.picker-footer span{font-size:13px;color:#64748b}.picker-layout{display:grid;grid-template-columns:200px minmax(0,1fr);gap:20px;margin:18px 0}.picker-layout>aside{display:grid;gap:14px;align-content:start;border-right:1px solid #e2e8f0;padding-right:16px}.picker-layout main{min-width:0}.picker-layout aside form,.picker-layout aside details{display:grid;gap:10px}.picker-layout aside label{display:grid;gap:6px;font-size:12px;color:#475569;margin-top:10px}.picker-layout select,.picker-layout input:not([type=checkbox]){min-width:0;width:100%;max-width:100%;padding:8px;border:1px solid #cbd5e1;border-radius:6px;background:white;box-sizing:border-box}.picker-layout aside summary,.selected-list summary{cursor:pointer;font-weight:600;font-size:13px}.picker-layout aside .label-option{display:flex;align-items:center}.picker-tools{margin-bottom:14px}.picker-rows{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px}.picker-material{border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;min-width:0}.picker-material.chosen{border-color:#3569c8;box-shadow:0 0 0 1px #3569c8}.picker-copy{padding:10px;overflow-wrap:anywhere}.picker-copy label{display:flex;align-items:flex-start;gap:6px;font-size:13px}.picker-copy p{font-size:12px;color:#64748b;margin:7px 0}.picker-copy .blocked-reason{color:#9a4b15}.list .picker-material{display:grid;grid-template-columns:130px minmax(0,1fr)}.frozen-selection{background:#f6f8fc;border:1px solid #dce4ef;padding:12px;border-radius:8px;display:grid;gap:6px;margin-bottom:12px;font-size:13px}.frozen-selection code{overflow-wrap:anywhere;font-size:11px}.selected-list{margin:10px 0 16px;border-bottom:1px solid #e2e8f0;padding-bottom:10px}.selected-list ul{max-height:160px;overflow:auto;padding:0;list-style:none}.selected-list li{display:flex;justify-content:space-between;gap:12px;font-size:12px}.selected-list li span{overflow-wrap:anywhere}.selected-list p{font-size:12px;color:#64748b}.picker-pagination{justify-content:center;margin-top:18px}.picker-footer{position:sticky;bottom:0;background:white;border-top:1px solid #e2e8f0;padding:14px 0 0;z-index:2}.picker-footer>div:first-child{display:grid;gap:5px}.text-action{border:0;background:transparent;color:#3569c8;cursor:pointer}@media(max-width:900px){.picker-layout{grid-template-columns:minmax(0,1fr)}.picker-layout>aside{border:0;padding:0;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.picker-layout>aside details:not([open]){align-self:start}.picker-rows{grid-template-columns:repeat(auto-fill,minmax(160px,1fr))}.picker-footer{padding-bottom:4px}}
</style>
